import os
import warnings

import pandas as pd
from sklearn.compose import ColumnTransformer
from sklearn.impute import SimpleImputer
from sklearn.model_selection import GroupShuffleSplit, StratifiedGroupKFold
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import KBinsDiscretizer, OneHotEncoder, StandardScaler

import config

# Binning a count column that is mostly zeros makes scikit-learn merge empty
# bins and print a warning for every fold. That merge is what we want, so the
# message is silenced here and in the worker processes used for tuning.
_QUIET = "ignore:Bins whose width are too small:UserWarning"
os.environ["PYTHONWARNINGS"] = ",".join(
    filter(None, [os.environ.get("PYTHONWARNINGS"), _QUIET]))
warnings.filterwarnings("ignore", message="Bins whose width are too small")

LABEL = "is_unsafe"
GROUP = "bin"

# The three feature steps of our experiment (see the project plan).
FEATURE_STEPS = {
    "1_filings_only": ("f_",),
    "2_plus_pluto": ("f_", "p_"),
    "3_plus_violations": ("f_", "p_", "v_"),
}


def load_table():
    if not config.TABLE_PATH.exists():
        raise FileNotFoundError(
            f"{config.TABLE_PATH} is missing. Run:  python -m src.build_table")
    return pd.read_csv(config.TABLE_PATH, dtype={GROUP: str, "bbl": str, "cycle": str},
                       parse_dates=["filing_date"])


def feature_columns(df, step):
    prefixes = FEATURE_STEPS[step]
    return [c for c in df.columns if c.startswith(prefixes)]


def split_by_building(df):
    """80/20 split by BUILDING, so no building is in both train and test."""
    splitter = GroupShuffleSplit(n_splits=1, test_size=config.TEST_SIZE,
                                 random_state=config.SEED)
    train_idx, test_idx = next(splitter.split(df, df[LABEL], groups=df[GROUP]))
    train, test = df.iloc[train_idx].copy(), df.iloc[test_idx].copy()
    assert not set(train[GROUP]) & set(test[GROUP]), "a building is in both sets"
    return train, test


def cv_folds():
    """5-fold cross-validation that keeps each building inside one fold."""
    return StratifiedGroupKFold(n_splits=config.CV_FOLDS, shuffle=True,
                                random_state=config.SEED)


def make_preprocessor(X, kind="scaled"):
    """Build the preparation step for a set of feature columns.

    kind="scaled": fill missing values, scale numbers, one-hot encode text.
                   Use for kNN, neural networks and anything distance-based.
    kind="plain" : same, but numbers are left unscaled. Use for trees.
    kind="binned": numbers are cut into 5 bins and one-hot encoded, so every
                   input is 0 or 1. Use for Bernoulli Naive Bayes.

    Everything is fitted on the training folds only, inside the pipeline.
    """
    numeric = [c for c in X.columns if pd.api.types.is_numeric_dtype(X[c])]
    text = [c for c in X.columns if c not in numeric]

    num_steps = [("fill", SimpleImputer(strategy="median", add_indicator=True))]
    if kind == "scaled":
        num_steps.append(("scale", StandardScaler()))
    elif kind == "binned":
        num_steps = [("fill", SimpleImputer(strategy="median")),
                     ("bin", KBinsDiscretizer(n_bins=5, encode="onehot-dense",
                                              strategy="quantile"))]
    elif kind != "plain":
        raise ValueError("kind must be 'scaled', 'plain' or 'binned'")

    text_steps = [("fill", SimpleImputer(strategy="constant", fill_value="MISSING")),
                  ("onehot", OneHotEncoder(handle_unknown="ignore", sparse_output=False))]

    if kind == "binned":
        # 0-1 flag columns are already binary: fill them, do not bin them.
        flags = [c for c in numeric if X[c].dropna().nunique() <= 2]
        numeric = [c for c in numeric if c not in flags]
        return ColumnTransformer([
            ("num", Pipeline(num_steps), numeric),
            ("flag", SimpleImputer(strategy="most_frequent"), flags),
            ("text", Pipeline(text_steps), text),
        ], verbose_feature_names_out=False)

    return ColumnTransformer([
        ("num", Pipeline(num_steps), numeric),
        ("text", Pipeline(text_steps), text),
    ], verbose_feature_names_out=False)
